{
  "goal": "Analyze quarterly sales CSV files for data quality issues, repair recoverable problems, revalidate repaired data, compute quarterly statistics, merge results, run a quality review, and generate a consolidated Markdown report with an evidence log.",
  "steps": [
    {
      "kind": "foreach",
      "name": "process_each_file",
      "over": "inputs",
      "description": "For each quarterly sales CSV: detect quality issues, repair, revalidate, and compute statistics.",
      "body": [
        {
          "kind": "primitive",
          "name": "parse_csv",
          "capability": "execute_python",
          "description": "Read and parse the current CSV file.",
          "code": "import csv\n\nfile_path = item\nwith open(file_path, 'r') as f:\n    reader = csv.DictReader(f)\n    rows = list(reader)\n    headers = reader.fieldnames\n\nenv['parsed_data'] = rows\nenv['file_headers'] = headers",
          "output": {
            "name": "parsed_data",
            "typeName": "List<Record>",
            "fields": []
          }
        },
        {
          "kind": "primitive",
          "name": "detect_issues",
          "capability": "execute_python",
          "description": "Detect data quality issues: schema drift, type errors, missing values, duplicates, outliers.",
          "code": "rows = parsed_data\n\nissues = {\n    'schema_drift': [],\n    'type_errors': [],\n    'missing_values': [],\n    'duplicates': [],\n    'outliers': []\n}\n\nseen = set()\nfor i, row in enumerate(rows):\n    row_tuple = tuple(sorted(row.items()))\n    if row_tuple in seen:\n        issues['duplicates'].append(i)\n    seen.add(row_tuple)\n\nfor i, row in enumerate(rows):\n    for col, val in row.items():\n        if val is None or val.strip() == '':\n            issues['missing_values'].append({'row': i, 'column': col})\n\nenv['detected_issues'] = issues",
          "inputBindings": [
            {"param": "parsed_data", "source": "parse_csv", "binding": "parsed_data"}
          ],
          "output": {
            "name": "detected_issues",
            "typeName": "Record",
            "fields": [
              {"name": "schema_drift", "typeName": "List"},
              {"name": "type_errors", "typeName": "List"},
              {"name": "missing_values", "typeName": "List"},
              {"name": "duplicates", "typeName": "List"},
              {"name": "outliers", "typeName": "List"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "repair_data",
          "capability": "execute_python",
          "description": "Repair recoverable data quality issues.",
          "code": "rows = parsed_data\nissues = detected_issues\n\nrepaired = list(rows)\n\nfor idx in sorted(issues['duplicates'], reverse=True):\n    if idx < len(repaired):\n        del repaired[idx]\n\nfor issue in issues['missing_values']:\n    row_idx = issue['row']\n    col = issue['column']\n    if row_idx < len(repaired):\n        repaired[row_idx][col] = '0'\n\nenv['repaired_data'] = repaired",
          "inputBindings": [
            {"param": "parsed_data", "source": "parse_csv", "binding": "parsed_data"},
            {"param": "detected_issues", "source": "detect_issues", "binding": "detected_issues"}
          ],
          "output": {
            "name": "repaired_data",
            "typeName": "List<Record>",
            "fields": []
          }
        },
        {
          "kind": "primitive",
          "name": "validate_repaired",
          "capability": "execute_python",
          "description": "Revalidate repaired data to confirm issues are resolved.",
          "code": "data = repaired_data\n\nvalidation = {\n    'total_rows': len(data),\n    'columns': list(data[0].keys()) if data else [],\n    'remaining_issues': 0\n}\n\nfor row in data:\n    for col, val in row.items():\n        if val is None or val.strip() == '':\n            validation['remaining_issues'] += 1\n\nenv['validation_result'] = validation",
          "inputBindings": [
            {"param": "repaired_data", "source": "repair_data", "binding": "repaired_data"}
          ],
          "output": {
            "name": "validation_result",
            "typeName": "Record",
            "fields": [
              {"name": "total_rows", "typeName": "Integer"},
              {"name": "columns", "typeName": "List<String>"},
              {"name": "remaining_issues", "typeName": "Integer"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "compute_stats",
          "capability": "execute_python",
          "description": "Compute quarterly statistics from validated data.",
          "code": "data = repaired_data\nvalidation = validation_result\n\nstats = {\n    'total_rows': validation['total_rows'],\n    'columns': validation['columns'],\n    'total_revenue': 0\n}\n\nfor row in data:\n    for col in row:\n        if 'revenue' in col.lower() or 'amount' in col.lower():\n            try:\n                stats['total_revenue'] += float(row[col])\n            except (ValueError, TypeError):\n                pass\n\nenv['quarterly_stats'] = stats",
          "inputBindings": [
            {"param": "repaired_data", "source": "repair_data", "binding": "repaired_data"},
            {"param": "validation_result", "source": "validate_repaired", "binding": "validation_result"}
          ],
          "output": {
            "name": "quarterly_stats",
            "typeName": "Record",
            "fields": [
              {"name": "total_rows", "typeName": "Integer"},
              {"name": "columns", "typeName": "List<String>"},
              {"name": "total_revenue", "typeName": "Number"}
            ]
          }
        }
      ],
      "output": {
        "name": "all_quarterly_stats",
        "typeName": "List<Record>",
        "fields": []
      }
    },
    {
      "kind": "primitive",
      "name": "merge_results",
      "capability": "execute_python",
      "description": "Merge all quarterly statistics into a single result.",
      "code": "stats_list = all_quarterly_stats\n\nmerged = {\n    'quarters_processed': len(stats_list),\n    'total_revenue': sum(s.get('total_revenue', 0) for s in stats_list),\n    'total_rows': sum(s.get('total_rows', 0) for s in stats_list),\n    'quarterly_details': stats_list\n}\n\nenv['merged_results'] = merged",
      "inputBindings": [
        {"param": "all_quarterly_stats", "source": "process_each_file", "binding": "all_quarterly_stats"}
